        {"대지":"제목", "내용":"왕의 잔치, 하나님의 계획", "예화_적용":"인간의 계획 이면에 하나님의 더 큰 계획이 숨겨져 있다"},
        {"대지":"서론", "내용":"아하수에로 왕이 제국의 모든 지도자를 초대해 성대한 잔치를 열었다. 겉으로는 화려한 축하연이었지만 실제로는 그리스 원정을 위한 군사회의였다. 인간의 계획 뒤에서 하나님은 에스더를 위한 무대를 준비하고 계셨다", "예화_적용":"역사의 큰 전환점은 종종 일상적인 사건으로 시작된다"},
        {"대지":"1대지: 왕위 제삼년 (하나님의 타이밍)", "내용":"이 시점은 에스더 등장 4년 전. 하나님은 이미 구원의 무대를 세팅하고 계셨다", "예화_적용":"지금 이해되지 않는 상황이 나중에 하나님의 계획이었음을 알게 된다"},
        {"대지":"2대지: 모든 지방관들의 잔치 (세상의 화려함)", "내용":"제국의 모든 귀족과 장수가 모인 화려한 연회. 그러나 이 화려함은 곧 교만과 갈등의 씨앗이 됨", "예화_적용":"외적 성공과 화려함에 취하지 않도록 경계해야 함"},
        {"대지":"3대지: 바사와 메대의 힘 (인간적 능력의 한계)", "내용":"세계 최강의 군사력도 하나님의 계획 앞에서는 도구에 불과함", "예화_적용":"우리의 능력과 자원이 아닌 하나님의 뜻을 먼저 구하자"},
        {"대지":"결론", "내용":"왕의 잔치는 끝나지만 하나님의 계획은 영원하다. 세상의 화려함에 현혹되지 말고 하나님의 영원한 잔치를 바라보자", "예화_적용":"계 19:9 어린 양의 혼인 잔치에 청함을 받은 자들은 복이 있다"}
