        {"교리":"7일의 상징", "설명":"창조의 7일을 연상시키는 기간. 그러나 하나님의 안식과 달리 왕의 7일은 향락으로 채워짐", "관련구절":"창 2:2-3, 출 20:11, 히 4:9-10"},
        {"교리":"인간적 에덴의 한계", "설명":"왕궁 정원은 에덴동산의 인간적 재현이지만, 참된 에덴은 오직 하나님만이 회복하실 수 있음", "관련구절":"창 2:8, 겔 28:13, 계 22:1-2"}
