        {"대지":"3대지: 일곱 내시에게 명령하여 (돌이킬 수 없는 명령)", "내용":"취중에 내린 명령이 일곱 내시를 통해 즉각 실행됨. 돌이킬 수 없는 결과로 이어짐", "예화_적용":"말과 행동에 신중해야 함. 한번 내뱉은 말은 돌이키기 어려움"},
        {"대지":"결론", "내용":"왕의 취중 명령은 어리석었지만 하나님의 섭리 안에서 에스더를 향한 길을 열었다. 인간의 실수도 하나님의 손 안에서 선한 목적으로 사용된다", "예화_적용":"롬 8:28 모든 것이 합력하여 선을 이루느니라"}
