        {"대지":"서론", "내용":"술에 취한 왕은 왕후를 데려와 그 아름다움을 보이라고 명했다. 180일간 나라의 부를 과시하고 이제 아내까지 과시하려 한 것이다. 이것은 인간을 전시품으로 취급하는 교만의 극치였다", "예화_적용":"SNS에서 타인을 외모로 판단하고 과시의 도구로 삼는 현대 문화를 반성해야 함"},
        {"대지":"1대지: 왕관을 씌워 (지위의 과시)", "내용":"왕관은 왕후의 지위를 상징. 그러나 왕은 이것을 자기 과시의 도구로 사용", "예화_적용":"하나님이 주신 지위와 은사를 자기 영광이 아닌 하나님의 영광을 위해 사용해야 함"},
        {"대지":"2대지: 아름다움을 보이게 하라 (인격의 도구화)", "내용":"왕후를 인격체가 아닌 전시품으로 취급. 하나님의 형상인 사람을 물건처럼 다루는 죄", "예화_적용":"사람을 외모나 능력으로만 평가하는 것은 하나님의 형상을 모독하는 것"},
        {"대지":"3대지: 아리따운 까닭이라 (외적 가치의 한계)", "내용":"왕이 중요시한 것은 오직 외적 아름다움. 그러나 참된 가치는 내면에 있음", "예화_적용":"벧전 3:3-4 외모의 꾸밈보다 온유하고 안정한 심령이 하나님 앞에 귀함"},
        {"대지":"결론", "내용":"왕의 명령은 교만했지만 하나님의 섭리는 이것을 에스더 등장의 통로로 사용하셨다. 인간의 교만한 계획 위에 하나님의 선한 뜻이 이루어진다", "예화_적용":"창 50:20 당신들은 나를 해하려 하였으나 하나님은 그것을 선으로 바꾸셨나이다"}
