        {"대지":"서론", "내용":"와스디는 단호하게 '아니오'라고 말했다. 고대 페르시아에서 왕의 명령을 거부하는 것은 목숨을 건 행동이었다. 그러나 그녀는 자신의 존엄성을 지켰다. 이 거절이 역사를 바꾸는 전환점이 되었다", "예화_적용":"로자 파크스가 버스에서 일어나기를 거부한 것처럼, 한 번의 거절이 역사를 바꿀 수 있다"},
        {"대지":"1대지: 왕후 와스디의 거절 (존엄성의 수호)", "내용":"부당한 명령 앞에서 자신의 존엄성을 지킨 용기. 죽음을 각오한 거절", "예화_적용":"행 5:29 사람보다 하나님께 순종하는 것이 마땅하니라"},
        {"대지":"2대지: 왕의 분노 (교만한 분노의 위험)", "내용":"거절당한 자존심이 불 같은 분노로 타오름. 분노가 더 큰 어리석음을 낳음", "예화_적용":"약 1:20 사람의 분노가 하나님의 의를 이루지 못함"},
        {"대지":"3대지: 섭리의 전환 (닫히는 문과 열리는 문)", "내용":"와스디의 거절은 비극이지만 에스더의 등장을 위한 섭리적 전환점", "예화_적용":"인생의 모든 거절과 위기가 하나님의 새로운 길을 여는 계기가 됨"},
        {"대지":"결론", "내용":"와스디의 '아니오'는 용기였고, 왕의 분노는 교만이었으며, 하나님의 섭리는 이 모든 것을 통해 구원의 역사를 준비하셨다", "예화_적용":"롬 8:28 모든 것이 합력하여 선을 이루느니라"}
