        {"대지":"결론", "내용":"왕의 얼굴을 보는 특권보다 하나님의 얼굴을 뵙는 특권이 더 크다. 기도로 그 특권을 날마다 누리자", "예화_적용":"엡 3:12 그리스도 안에서 우리가 담대함과 확신을 가지고 하나님께 나아감을 얻느니라"}
