        {"대지":"1대지: 멸시의 시작 (갈등의 씨앗)", "내용":"와스디의 거부가 멸시로 해석됨. 상대방의 행동을 악의적으로 해석하는 것이 갈등의 시작", "예화_적용":"선의로 해석하는 습관이 갈등을 예방한다"},
        {"대지":"2대지: 분노의 확산 (갈등의 연쇄)", "내용":"멸시가 분노를 낳고 분노가 더 큰 갈등을 초래하는 악순환", "예화_적용":"분노를 즉시 다루지 않으면 뿌리를 내림 (엡 4:26)"},
        {"대지":"3대지: 십자가의 화해 (갈등의 해결)", "내용":"인간적으로는 끊을 수 없는 갈등의 연쇄를 그리스도의 십자가가 끊으심", "예화_적용":"엡 2:14 그는 우리의 화평이시라"},
        {"대지":"결론", "내용":"멸시와 분노의 악순환을 끊는 유일한 방법은 십자가의 사랑이다. 먼저 용서하고 화해의 손을 내미는 것이 그리스도인의 사명이다", "예화_적용":"마 5:9 화평하게 하는 자는 복이 있나니 하나님의 아들이라 일컬음을 받을 것임이요"}
