        {"구분":"남편이 집을 주관하게", "내용":"가정의 질서를 법으로 세우려 함", "그리스도연결":"교회를 머리로서 사랑으로 다스리시는 그리스도 (엡 5:23-25)"},
        {"구분":"1장의 마무리와 새 시작", "내용":"한 시대의 마감과 새 시대의 시작", "그리스도연결":"옛 것은 지나가고 새 것이 되는 복음 (고후 5:17)"}
