        {"대지":"3대지: 1장에서 2장으로 (어리석음에서 섭리로)", "내용":"인간의 어리석은 결정이 끝나고 하나님의 새로운 역사가 시작됨", "예화_적용":"고전 1:25 하나님의 어리석음이 사람보다 지혜 있고"},
        {"대지":"결론", "내용":"에스더 1장이 끝났다. 와스디는 사라지고 왕후의 자리가 비었다. 이 빈자리를 하나님은 에스더로 채우실 것이다. 인간의 어리석음이 끝나는 곳에서 하나님의 지혜가 시작된다", "예화_적용":"사 55:8 내 생각은 너희의 생각과 다르며 내 길은 너희의 길과 다르니라"}
