        {"항목":"고대 근동의 미인 선발", "내용":"고대 페르시아뿐 아니라 바벨론, 앗시리아에서도 왕실 후궁을 위한 미인 선발이 있었음. 헤로도토스도 이런 관행을 기록", "목회적활용":"이방 문화의 관행 속에서도 하나님은 자기 백성을 높이 세우신다"}
