        {"원어":"תַּמְרוּקֵיהֶן (타므루케헨)", "의미_문법":"화장품/정결제 - 명사 복수. 미용을 위한 향료와 화장품", "설교포인트":"외적 단장보다 내면의 아름다움이 참된 준비이다"}
