        {"항목":"와스디 대신의 의미", "내용":"와스디의 폐위로 생긴 빈자리가 에스더의 기회가 됨. 역사의 전환점", "목회적활용":"한 사람의 퇴장이 다른 사람의 부르심이 되는 섭리"}
