        {"원어":"אֶסְתֵּר (에스테르)", "의미_문법":"에스더 - 고유명사. 페르시아어 '별(star)'또는 바벨론 여신 이쉬타르에서 유래", "설교포인트":"어둠 속에서 빛나는 별처럼 위기 속에서 빛나는 믿음의 여성"},
        {"원어":"יְפַת־תֹּאַר (예파트 토아르)", "의미_문법":"용모가 곱고 - 형용사구. 외형이 아름다운", "설교포인트":"외적 아름다움은 하나님의 선물이며 내적 아름다움과 함께할 때 빛난다"},
        {"원어":"לְבַת (레바트)", "의미_문법":"딸같이 - 전치사+명사. 양녀로 삼음을 표현", "설교포인트":"혈연을 넘어선 사랑이 하나님의 양자 삼으시는 은혜를 반영한다"}
