        {"항목":"고아의 양육", "내용":"고대 근동에서 친척이 고아를 양육하는 것은 의무이자 미덕. 모르드개가 삼촌의 딸을 자기 딸같이 양육한 것은 가족 책임의 모범", "목회적활용":"공동체 안에서 돌봄의 사명을 실천하는 것의 중요성"},
        {"항목":"에스더의 배경", "내용":"부모를 잃은 고아, 포로의 후손, 소수 민족 여성이라는 삼중 약자의 위치. 그러나 하나님은 이 약자를 제국의 왕후로 세우심", "목회적활용":"세상에서 가장 연약한 위치에 있는 사람도 하나님의 위대한 도구가 될 수 있다"}
