        {"교리":"거룩한 순종", "설명":"어려운 상황에서의 순종이 하나님의 더 큰 뜻을 이루는 통로가 됨", "관련구절":"빌 2:8, 히 5:8, 삼상 15:22"},
        {"교리":"하나님의 보호하심", "설명":"이방 왕궁이라는 위험한 환경에서 헤개를 통해 에스더를 보호하심", "관련구절":"시 23:4, 사 43:2, 단 6:22"}
