        {"영어원문":"When the king's command was proclaimed, many young women were gathered to the citadel of Susa, including Esther.", "한국어번역":"왕의 명령이 반포되매 에스더를 포함하여 많은 젊은 여인들이 수산 궁에 모였다.", "핵심통찰":"하나님은 세상의 명령을 통해서도 자기 백성을 계획된 위치에 두신다"},
        {"영어원문":"Esther did not seek the crown, but God's providence brought her to the place appointed for her.", "한국어번역":"에스더는 왕관을 구하지 않았으나 하나님의 섭리가 그녀를 지정된 곳으로 데려왔다.", "핵심통찰":"구하지 않아도 하나님이 정하신 자리에 서게 하신다"},
        {"영어원문":"The same hand that directed Joseph to Pharaoh's court directed Esther to Ahasuerus's palace.", "한국어번역":"요셉을 바로의 궁으로 인도한 바로 그 손이 에스더를 아하수에로의 궁으로 인도하였다.", "핵심통찰":"구약의 구원 패턴은 반복된다 - 위기 속의 배치"}
