        {"대지":"서론", "내용":"에스더는 자원하여 왕궁에 간 것이 아니다. 왕의 칙령에 의해 끌려갔다. 그러나 이 비자발적인 길이 민족 구원의 길이 되었다. 때로 하나님은 우리가 원하지 않는 길을 통해 가장 위대한 뜻을 이루신다", "예화_적용":"요셉이 형들에 의해 끌려간 이집트가 구원의 땅이 되었듯이"},
        {"대지":"1대지: 칙령의 강제력 (통제할 수 없는 상황)", "내용":"왕의 명령 앞에 개인의 선택은 무력. 그러나 왕명 위에 하나님의 명령이 있다", "예화_적용":"코로나 팬데믹처럼 통제 불가능한 상황에서도 하나님은 역사하신다"},
        {"대지":"2대지: 헤개의 관할 (하나님이 보내신 사람)", "내용":"낯선 왕궁에서 에스더를 돌보는 이방인 헤개 - 하나님이 예비하신 돌봄의 사람", "예화_적용":"이방 땅에서 만나는 선한 사람들은 하나님이 보내신 천사일 수 있다"},
        {"대지":"3대지: 많은 처녀 중 하나 (겸손한 시작)", "내용":"수많은 후보 중 한 사람으로 시작한 에스더 - 겸손한 시작이 위대한 결말로", "예화_적용":"겨자씨 같은 작은 시작이 큰 나무가 되는 천국의 원리 (마 13:31-32)"},
        {"대지":"결론", "내용":"지금 겪는 비자발적 상황이 하나님의 자발적 계획일 수 있다. 끌려가는 길 위에서도 인도하시는 하나님을 신뢰하라", "예화_적용":"사도 바울이 로마로 끌려간 것이 복음 전파의 통로가 되었듯이 (행 28:30-31)"}
