        {"구분":"때를 기다리는 침묵", "내용":"적절한 때까지 정체를 밝히지 않음", "설교포인트":"하나님의 때가 올 때까지 감춰진 메시아의 비밀 (막 8:30)"},
        {"구분":"모르드개의 명령과 에스더의 순종", "내용":"양부의 지시에 절대적으로 순종함", "그리스도연결":"아버지의 뜻에 전적으로 순종하신 예수 그리스도 (요 6:38)"}
