        {"대지":"결론", "내용":"지금 겪는 고난의 몰약과 성장의 향품이 우리를 왕 앞에 설 준비를 시키고 있다. 과정을 신뢰하라", "예화_적용":"로마서 5:3-4 환난은 인내를, 인내는 연단을, 연단은 소망을 이룬다"}
