        {"대지":"2대지: 멘토의 조언에 순종 (지혜로운 순종)", "내용":"헤개의 조언만 따름 - 전문가의 지혜에 겸손히 순종하는 것", "예화_적용":"나아만 장군이 엘리사의 지시에 순종하여 치유받았듯이 (왕하 5:14)"},
        {"대지":"3대지: 만인의 호의 (하나님의 은혜의 열매)", "내용":"보는 자마다 사랑을 받음 - 겸손한 자에게 하나님이 은혜를 주심", "예화_적용":"잠언 3:34 겸손한 자에게는 은혜를 베푸신다"},
        {"대지":"결론", "내용":"참된 아름다움은 화려한 외면이 아니라 겸손한 내면에서 나온다. 구하지 않아도 주시는 하나님의 은혜를 경험하라", "예화_적용":"벧전 3:3-4 단장은 머리를 꾸미고 금을 차고 아름다운 옷을 입는 것이 아니라 마음에 숨은 사람을 온유하고 안정한 심령의 썩지 아니할 것으로 하라"}
