        {"항목":"고아에서 왕후로", "내용":"부모 없는 포로 민족의 고아 소녀가 세계 최강 제국의 왕후가 되는 놀라운 역전. 역사상 가장 극적인 신분 상승 중 하나", "목회적활용":"하나님의 은혜 앞에 불가능은 없다"},
        {"항목":"에스더의 등극 시기", "내용":"BC 479/478년경 에스더가 왕후가 됨. 이후 약 5년 뒤(제12년) 하만의 유대인 학살 음모가 발생. 에스더의 위치가 구원의 핵심 통로가 됨", "목회적활용":"현재의 영광이 미래의 사명을 위한 것임"}
