    표5_매튜헨리: [
        {"영어원문":"The king loved Esther above all the women and set the royal crown upon her head.", "한국어번역":"왕이 모든 여자보다 에스더를 사랑하여 왕후의 관을 그의 머리에 씌웠다.", "핵심통찰":"하나님의 특별한 사랑이 불가능한 역전을 이루어낸다"},
        {"영어원문":"From a poor captive to a queen — such is the transforming power of God's providence.", "한국어번역":"가난한 포로에서 왕후로 — 이것이 하나님 섭리의 변혁적 능력이다.", "핵심통찰":"하나님의 섭리는 인생을 완전히 뒤집을 수 있다"},
        {"영어원문":"The crown upon Esther's head was not merely ornamental but strategic for the preservation of God's people.", "한국어번역":"에스더 머리의 왕관은 단순한 장식이 아니라 하나님의 백성 보존을 위한 전략적 배치였다.", "핵심통찰":"하나님이 주시는 영광에는 반드시 사명이 따른다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"고아에서 왕후로: 은혜의 왕관", "예화_적용":"하나님의 은혜는 가장 낮은 곳에서 가장 높은 곳으로 올리신다"},
        {"대지":"서론", "내용":"부모 없는 고아, 포로 민족의 소녀, 이방 땅의 약자. 그런 에스더의 머리에 세계 최강 제국의 왕관이 씌워졌다. 이것은 에스더의 능력이 아니라 하나님의 은혜의 역사이다", "예화_적용":"요셉이 감옥에서 총리가, 다윗이 양치기에서 왕이 되었듯이"},
        {"대지":"1대지: 사랑의 선택 (왕의 마음)", "내용":"왕이 모든 여자보다 에스더를 더 사랑함 - 하나님이 왕의 마음을 움직이심", "예화_적용":"잠 21:1 왕의 마음이 여호와의 손에 있어 물줄기 같이 인도하심"},
        {"대지":"2대지: 왕관의 영광 (하나님의 높이심)", "내용":"왕후의 관을 씌움 - 하나님이 높이시면 아무도 낮출 수 없다", "예화_적용":"시편 113:7-8 가난한 자를 먼지 더미에서 일으키시며"},
        {"대지":"3대지: 영광의 사명 (왕관 뒤의 책임)", "내용":"왕관은 장식이 아니라 민족 구원의 도구 - 영광에는 사명이 따름", "예화_적용":"에스더 4:14 네가 왕후의 자리를 얻은 것이 이 때를 위함이 아닌지"},
        {"대지":"결론", "내용":"하나님이 주시는 왕관은 나를 위한 것이 아니라 다른 사람을 위한 것이다. 받은 은혜를 나누는 삶이 왕관의 참된 의미이다", "예화_적용":"누가복음 12:48 많이 받은 자에게 많이 요구하시리라"}
    ],
