        {"원어":"קָצַף (카차프)", "의미_문법":"노하다/분노하다 - 동사 칼형. 왕에 대한 분노", "설교포인트":"통제되지 않는 분노는 파괴적 결과를 낳는다"},
        {"원어":"לִשְׁלֹחַ יָד (리쉬로아흐 야드)", "의미_문법":"손을 뻗다/해치다 - 관용구. 암살을 시도함", "설교포인트":"악한 계획은 반드시 하나님에 의해 드러난다"}
