        {"원어":"אֲגָגִי (아가기)", "의미_문법":"아각 사람 - 형용사. 아말렉 왕 아각의 후손", "설교포인트":"과거의 미완의 대결이 새로운 세대에서 재현된다"},
        {"원어":"גִּדַּל (기달)", "의미_문법":"높이다/크게 하다 - 동사 피엘형. 지위를 크게 올림", "설교포인트":"인간이 높인 자와 하나님이 높이신 자의 결말은 다르다"},
        {"원어":"נָשָׂא (나사)", "의미_문법":"들어올리다/높이다 - 동사 칼형. 모든 대신 위의 자리", "설교포인트":"높아질수록 교만의 위험이 커진다"}
