        {"항목":"하만의 승진", "내용":"아하수에로 왕이 하만을 모든 대신 위의 자리, 즉 총리대신(비지르)에 임명. 제국에서 왕 다음가는 권력자가 됨", "목회적활용":"세상의 권력은 하나님의 허락 없이는 유지되지 못한다"},
        {"항목":"에스더서의 전환점", "내용":"이 시점부터 에스더서의 갈등이 본격적으로 시작됨. 하만의 등장이 유대인 학살 위기의 시작", "목회적활용":"위기의 시작에도 하나님의 섭리가 이미 준비되어 있다"}
