        {"영어원문":"Haman was an Agagite, a descendant of the ancient enemy of Israel, and his rise foreshadowed the conflict to come.", "한국어번역":"하만은 아각 사람으로 이스라엘의 고대 원수의 후손이며, 그의 부상은 다가올 갈등을 예고하였다.", "핵심통찰":"역사적 대결이 새로운 형태로 재현되지만 하나님의 최종 승리는 변하지 않는다"},
        {"영어원문":"The higher wicked men are raised, the more signal will be their fall.", "한국어번역":"악인이 높이 올려질수록 그 추락은 더욱 극적이 될 것이다.", "핵심통찰":"높이 올라간 교만은 더 크게 무너진다"}
