        {"원어":"הִגִּיד (힉기드)", "의미_문법":"알리다/밝히다 - 동사 히필형. 자발적 정체성 공개", "설교포인트":"때가 되면 신앙의 정체성을 담대히 드러내야 한다"},
        {"원어":"יַעַמְדוּ (야아메두)", "의미_문법":"서다/유지되다 - 동사 칼형. 그의 입장이 유지되는지 지켜봄", "설교포인트":"신앙적 결단은 지켜보는 세상에게 증거가 된다"}
