        {"영어원문":"The wrath of the wicked against the righteous always overreaches and eventually destroys the wicked themselves.", "한국어번역":"의인에 대한 악인의 분노는 항상 도를 넘고 결국 악인 자신을 파괴한다.", "핵심통찰":"악인의 분노는 부메랑이 되어 자기를 파괴한다"}
