        {"원어":"כָּל הַיְּהוּדִים (콜 하예후딤)", "의미_문법":"모든 유대인 - 명사구. 제국 전체의 유대인을 대상으로", "설교포인트":"악은 개인에서 시작하여 전체를 삼키려 한다"},
        {"원어":"עַם מָרְדֳּכַי (암 모르도카이)", "의미_문법":"모르드개의 민족 - 명사구. 유대 민족 전체", "설교포인트":"한 사람의 신앙이 민족 전체의 운명과 연결된다"}
