        {"대지":"2대지: 악인에게 넘어간 권위 (남용의 위험)", "내용":"하만이 왕의 권위를 개인 원한에 사용 - 권력 남용", "예화_적용":"권력은 부패한다, 절대 권력은 절대 부패한다 (액턴 경)"},
        {"대지":"3대지: 돌아오는 반지 (하나님의 역전)", "내용":"에스더 8:2에서 하만의 반지가 모르드개에게 돌아감", "예화_적용":"악인이 빼앗은 것은 반드시 의인에게 돌아온다"},
        {"대지":"결론", "내용":"지금 악인이 권위를 쥐고 있더라도 낙심하지 말라. 하나님은 때가 되면 반드시 권위를 바로잡으신다. 반지는 돌아온다", "예화_적용":"골 2:15 정사와 권세를 벗어버려 공개적으로 구경거리로 삼으시고 십자가로 승리하시니라"}
