        {"항목":"은의 거래", "내용":"학자들은 왕이 은을 거절한 것(동양식 겸양)이 아니라 실제로 하만에게 맡긴 것으로 해석. 에 4:7에서 하만이 은을 바치겠다고 한 것을 에스더가 알고 있음", "목회적활용":"돈과 권력의 부패한 결합이 생명을 위협한다"},
        {"항목":"백성을 넘겨줌", "내용":"왕이 자기 백성을 하만에게 넘겨준 것은 통치자의 가장 큰 실패. 백성을 보호해야 할 왕이 백성을 포기함", "목회적활용":"참된 지도자는 백성을 보호하지 포기하지 않는다"}
