        {"원어":"בּוֹא (보)", "의미_문법":"들어가다-Qal 부정사, 출입이 허용되지 않음을 표현", "설교포인트":"인간의 규칙이 막을 수 있는 것은 물리적 접근뿐, 영적 접근은 막지 못합니다"}
