        {"항목":"대궐 문의 의미", "내용":"왕의 문은 공적 업무와 재판이 이루어지는 장소로, 모르드개의 근무지이자 정보 수집의 중심지", "목회적활용":"일상적 삶의 자리가 영적 전쟁의 현장이 됩니다"},
        {"항목":"접근의 제한", "내용":"애도복을 입은 자의 궁정 출입 금지는 왕에게 불쾌한 것을 보이지 않으려는 페르시아의 관습", "목회적활용":"인간의 제도적 한계 앞에서도 포기하지 않는 신앙이 필요합니다"}
