        {"항목":"각 지방의 반응", "내용":"페르시아 제국 127개 지방 전역에 거주하는 유대인들이 동시에 반응한 것으로, 디아스포라 유대인의 연대감을 보여줌", "목회적활용":"흩어져 있어도 하나 된 마음으로 기도하는 것이 영적 연합의 힘입니다"},
        {"항목":"재에 누움", "내용":"재에 눕는 것은 금식과 울음보다 더 극단적인 애도 형태로, 완전한 자기 부인과 하나님 앞에서의 절대적 겸손을 표현", "목회적활용":"가장 낮은 곳에서 부르짖을 때 가장 높은 곳에서 응답하십니다"}
