        {"원어":"שַׁרְבִיט (샤르빗)", "의미_문법":"규/홀-남성명사, 왕의 권위와 은총의 상징", "설교포인트":"왕의 금 규는 하나님의 은혜를 상징하며, 은혜가 율법을 이깁니다"},
        {"원어":"חָיָה (하야)", "의미_문법":"살다-Qal 완료형, 생존이 허락됨", "설교포인트":"생사여탈의 권한이 왕에게 있지만, 궁극적으로 하나님께 있습니다"},
        {"원어":"שְׁלוֹשִׁים (쉘로쉼)", "의미_문법":"삼십-수사, 30일 동안 부름받지 못함", "설교포인트":"기다림의 시간이 길어도 하나님의 때가 있습니다"}
