        {"항목":"금 규", "내용":"왕이 금 규(홀)를 내미는 것은 접근을 허락하고 생명을 보장하는 은총의 표시로, 왕의 재량에 전적으로 달려 있었음", "목회적활용":"은혜란 받을 자격이 없는 자에게 베푸는 호의이며, 이것이 복음의 핵심입니다"},
        {"항목":"30일간 부름 없음", "내용":"에스더가 30일간 왕의 부름을 받지 못한 것은 왕의 총애가 줄어들고 있을 수 있다는 불안을 암시", "목회적활용":"하나님의 침묵처럼 느껴지는 시간에도 하나님은 역사하고 계십니다"}
