        {"항목":"왕의 기쁨", "내용":"왕이 에스더를 보고 기뻐한 것은 하나님이 왕의 마음을 움직이신 결과로, 에스더의 기도와 금식에 대한 하나님의 응답", "목회적활용":"왕의 마음도 하나님의 손에 있습니다 (잠 21:1)"},
        {"항목":"에스더의 접근", "내용":"에스더가 금 규 끝을 만진 것은 은혜를 받아들이는 행위로, 수동적이 아닌 능동적 수용을 보여줌", "목회적활용":"은혜는 일방적으로 주어지지만, 그것을 받아들이는 믿음의 행동이 필요합니다"}
