        {"원어":"בַּיִת (바이트)", "의미_문법":"집-남성명사, 가정이라는 사적 공간", "설교포인트":"공적으로 참은 분노를 사적으로 풀어놓는 것은 위험합니다"},
        {"원어":"אֹהֲבִים (오하빔)", "의미_문법":"친구들-Qal 분사 남성복수, 사랑하는 자들/동조자들", "설교포인트":"교만한 자의 친구는 아첨꾼일 뿐, 진정한 조언자가 아닙니다"},
        {"원어":"זֶרֶשׁ (제레쉬)", "의미_문법":"세레스-고유명사, 하만의 아내 이름으로 '금'이라는 뜻", "설교포인트":"배우자의 조언이 하나님의 뜻에 합당한지 분별해야 합니다"}
