        {"구절":"전 8:14", "연결점":"의인에게 악인의 행위대로 되는 불공평한 현실", "구분":"구약"},
        {"구절":"시 73:1-17", "연결점":"악인의 형통과 의인의 고난에 대한 탄식과 깨달음", "구분":"구약"},
        {"구절":"창 50:20", "연결점":"악을 선으로 바꾸시는 하나님의 섭리", "구분":"구약"},
        {"구절":"시 37:5-6", "연결점":"네 길을 여호와께 맡기라 그가 이루시리라", "구분":"구약"},
        {"구절":"마 6:4", "연결점":"은밀한 중에 보시는 아버지가 갚으시리라", "구분":"신약"},
        {"구절":"고후 5:10", "연결점":"그리스도의 심판석 앞에서 선악의 보응을 받으리라", "구분":"신약"},
        {"구절":"벧전 5:6", "연결점":"때가 되면 너희를 높이시리라", "구분":"신약"},
        {"구절":"딤후 4:8", "연결점":"의의 면류관을 주실 것이니", "구분":"신약"}
