    표5_매튜헨리: [
        {"영어원문":"Haman was so puffed up with his own conceit that he could not imagine the king should mean to do honour to any one but himself.", "한국어번역":"하만은 자만심에 너무 부풀어 올라 왕이 자신 외에 다른 누구를 존귀케 하려 한다는 것을 상상할 수 없었다.", "핵심통찰":"교만은 현실 인식을 왜곡시킨다"},
        {"영어원문":"Pride is a sin that often makes men ridiculous, and sets them up to be the instruments of their own confusion.", "한국어번역":"교만은 사람을 우스꽝스럽게 만들고, 스스로 자기 혼란의 도구가 되게 하는 죄이다.", "핵심통찰":"교만이 자초하는 파멸"},
        {"영어원문":"God delights to abase the proud and to honour those whom they despise.", "한국어번역":"하나님은 교만한 자를 낮추시고 그들이 멸시하는 자를 높이시기를 기뻐하신다.", "핵심통찰":"하나님의 역전 원리"}
    ],
