        {"교리":"하만의 과도한 요구", "설명":"하만이 요청한 것들은 왕의 고유한 권한에 속하는 것으로, 사실상 왕과 동등한 지위를 요구한 것이다", "관련구절":"사 14:14, 겔 28:2, 빌 2:6"},
        {"교리":"외적 영광과 내적 실질", "설명":"왕복, 말, 왕관은 외적 영광이나 참된 존귀는 내적 품성에서 온다", "관련구절":"삼상 16:7, 벧전 3:3-4, 마 23:27-28"}
