    표5_매튜헨리: [
        {"영어원문":"Haman prescribes the royal apparel, the royal steed, and the royal crown, all that could express the greatest honour.", "한국어번역":"하만은 왕복, 왕의 말, 왕관 등 최고의 영예를 표현할 수 있는 모든 것을 제안하였다.", "핵심통찰":"교만한 자의 과도한 욕망"},
        {"영어원문":"The proud man aims at nothing less than the highest place; he would be as the king himself.", "한국어번역":"교만한 자는 최고의 자리 외에는 아무것도 목표하지 않으며, 그는 왕 자신과 같아지려 한다.", "핵심통찰":"왕과 동등해지려는 교만"},
        {"영어원문":"It is the nature of pride to covet distinction and to seek to be admired above all others.", "한국어번역":"교만의 본질은 차별적 대우를 탐내고 모든 사람 위에서 찬사를 받으려 하는 것이다.", "핵심통찰":"교만의 본질은 자기과시"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"왕복과 말과 왕관 - 참된 영광의 상징을 찾아서", "예화_적용":"세상의 영광과 하나님이 주시는 영광의 차이"},
        {"대지":"서론", "내용":"하만은 왕복, 왕의 말, 왕관이라는 최고의 영예를 설계한다. 이것은 사실상 왕과 동등한 지위를 원하는 교만의 표현이었다", "예화_적용":"알렉산더 대왕이 세계를 정복하고도 더 정복할 세계가 없다고 울었다는 일화처럼, 세상의 영광은 채울 수 없는 욕망이다"},
        {"대지":"1대지: 왕복 (정체성의 상징)", "내용":"왕복을 입는다는 것은 왕의 정체성을 부여받는 것이다. 하나님은 우리에게 그리스도의 의를 입혀주신다", "예화_적용":"탕자가 돌아왔을 때 아버지가 상등 옷을 입혀준 것처럼(눅 15:22), 하나님은 우리에게 은혜의 옷을 입혀주신다"},
        {"대지":"2대지: 왕의 말 (권위의 상징)", "내용":"왕의 말을 타는 것은 왕의 권위를 위임받는 것이다. 참된 권위는 섬김에서 온다", "예화_적용":"예수님이 나귀를 타고 예루살렘에 입성하신 것은 섬기는 왕의 모습이었다(마 21:5)"},
        {"대지":"3대지: 왕관 (영광의 상징)", "내용":"왕관은 최고의 영예이나, 썩을 면류관이 아닌 썩지 않을 면류관을 사모해야 한다", "예화_적용":"올림픽 금메달리스트의 영광은 잠시이나, 고전 9:25 썩지 아니할 면류관을 받기 위해 절제하는 자가 되자"},
        {"대지":"결론", "내용":"세상의 왕복, 말, 왕관보다 그리스도의 의와 하나님의 영광을 추구하는 삶이 참된 영광이다", "예화_적용":"골 3:2 위의 것을 찾으라 거기는 그리스도께서 하나님 우편에 앉아 계시느니라"}
    ],
