        {"새찬송가":"204", "통일찬송가":"143", "제목":"만 입이 내게 있으면", "선정이유":"참된 왕이신 하나님을 찬양"},
        {"새찬송가":"21", "통일찬송가":"21", "제목":"주 하나님 지으신 모든 세계", "선정이유":"만왕의 왕이신 하나님의 위엄"}
