        {"영어원문":"What a mortification was this to Haman! How was he thunderstruck when the king named Mordecai!", "한국어번역":"이것이 하만에게 얼마나 큰 굴욕이었겠는가! 왕이 모르드개의 이름을 말했을 때 그는 얼마나 벼락을 맞은 듯했겠는가!", "핵심통찰":"교만한 자에게 임한 갑작스러운 굴욕"},
        {"영어원문":"God can make the enemies of His people to serve them, and that which was designed for their ruin to be turned to their advancement.", "한국어번역":"하나님은 자기 백성의 원수들이 그들을 섬기게 하실 수 있으며, 그들의 파멸을 위해 계획된 것을 그들의 승진으로 뒤바꾸실 수 있다.", "핵심통찰":"하나님이 원수를 섬김의 도구로 사용하심"}
