        {"상황":"실패와 수치로 번민하는 분", "성경원리":"하만의 번민은 교만의 결과이지만, 회개하면 회복의 기회가 있다", "실제적용":"수치스러운 상황에서 자기 연민에 빠지기보다 하나님 앞에 겸손히 나아가 회개하라"},
        {"상황":"자기 자리에 불만족하는 분", "성경원리":"모르드개는 대궐 문이라는 겸손한 자리에 만족하며 충성했다", "실제적용":"현재의 위치에서 충성하는 것이 더 큰 축복의 통로가 됨을 기억하라. 눅 16:10 지극히 작은 것에 충성된 자는 큰 것에도 충성되리라"}
