        {"교리":"이방인의 증언", "설명":"하만의 아내와 지혜자들이 유대인의 하나님의 보호를 인정하는 것은 이방인의 증언이다", "관련구절":"수 2:9-11, 출 18:11, 단 3:28-29"},
        {"교리":"확실한 패망의 선언", "설명":"나폴 팁폴(반드시 넘어지리라)이라는 강조 구문은 하나님을 대적하는 자의 확실한 패배를 선언한다", "관련구절":"시 2:1-4, 사 54:17, 롬 8:31"}
