        {"항목":"하만의 동석", "내용":"하만도 이 잔치에 초대받았는데 이는 에스더의 의도적 계획으로 왕 앞에서 직접 하만을 고발하기 위함이었다", "목회적활용":"하나님은 악인의 행보까지도 심판의 자리로 인도하신다"}
