        {"상황":"평범한 일상이 무의미하게 느껴지는 분", "성경원리":"평범한 잔치 자리가 민족 구원의 현장이 된 것처럼 하나님은 일상 속에서 역사하신다", "실제적용":"매일의 작은 순간들이 하나님의 큰 계획의 일부임을 깨닫도록 안내한다"}
