    표5_매튜헨리: [
        {"영어원문":"Write ye also for the Jews as it liketh you, in the king's name. What a power was hereby put into their hands!", "한국어번역":"유다인을 위해 너희 뜻대로 왕의 이름으로 쓰라. 이로써 얼마나 큰 권한이 그들의 손에 주어졌는가!", "핵심통찰":"왕으로부터 위임받은 전권"},
        {"영어원문":"That which is written in the king's name and sealed with the king's ring may not be reversed. God's decrees are unalterable.", "한국어번역":"왕의 이름으로 쓰고 왕의 반지로 인친 것은 되돌릴 수 없다. 하나님의 작정은 변경할 수 없다.", "핵심통찰":"하나님의 작정의 불변성"},
        {"영어원문":"Though the first edict could not be revoked, a second was issued to counteract its effects. Grace does not destroy the law but provides a remedy.", "한국어번역":"첫 번째 조서를 취소할 수 없었지만 그 효과를 상쇄하는 두 번째 조서가 발행되었다. 은혜는 율법을 파괴하지 않고 치유책을 제공한다.", "핵심통찰":"율법을 폐하지 않는 은혜"}
    ],
