        {"대지":"3대지: 취소할 수 없는 조서 (확실한 약속)", "내용":"왕의 인장으로 인친 것은 변할 수 없듯 하나님의 약속도 변치 않음", "예화_적용":"엡 1:13-14 성령으로 인치심을 받은 구원의 보증"},
        {"대지":"결론", "내용":"죽음의 율법 위에 생명의 은혜가 선포되었다. 예수 그리스도의 이름으로 우리에게 주어진 새 조서를 기뻐하자", "예화_적용":"롬 8:1 그리스도 예수 안에 있는 자에게는 결코 정죄함이 없나니"}
