        {"대지":"3대지: 각 민족의 언어로 (보편적 선포)", "내용":"127개 도, 각 문자, 각 언어로 조서가 전달됨", "예화_적용":"행 2:8 각 사람의 난 곳 방언으로 복음을 들음"},
        {"대지":"결론", "내용":"하나님의 구원의 조서는 모든 민족, 모든 언어에 전해져야 한다. 우리도 이 생명의 조서를 전하는 사자가 되자", "예화_적용":"롬 10:15 좋은 소식을 전하는 자들의 발이 어찌 그리 아름다운고"}
