        {"항목":"두려움(파하드)의 확산", "내용":"모르드개의 권세 상승과 왕의 새 조서로 인해 유다인에 대한 공포가 제국 전역에 퍼짐", "목회적활용":"하나님이 자기 백성을 위해 싸우실 때 원수가 두려워함"},
        {"항목":"자기 방어권", "내용":"에 8:11의 조서에 따라 유다인은 합법적으로 자기를 방어할 권리를 얻었으며 이는 페르시아 법 체계 안에서의 합법적 행위", "목회적활용":"하나님은 합법적 수단을 통해서도 백성을 보호하심"}
