        {"대지":"서론", "내용":"페르시아 제국 127개 도에 흩어져 있던 유다인들이 생사의 위기 앞에서 하나로 모였다. 그때 놀라운 일이 일어났다", "예화_적용":"한국교회 1907년 평양대부흥 때 성도들이 하나로 모여 기도하자 놀라운 역사가 일어남"},
        {"대지":"1대지: 모여 연합하다 (성도의 결집)", "내용":"각 도 각 성에서 유다인이 모였다. 흩어져 있었지만 위기 앞에서 하나가 되었다", "예화_적용":"초대교회 성도들이 핍박 앞에서 한마음으로 기도한 결과 성령이 임하심 (행 4:31)"},
        {"대지":"2대지: 두려움이 임하다 (하나님의 역사)", "내용":"모든 백성이 유다인을 두려워했다. 이 두려움은 인간의 힘이 아니라 하나님이 주신 것이다", "예화_적용":"기드온의 300명이 미디안 대군을 두렵게 한 것처럼 하나님이 주시는 두려움 (삿 7장)"},
        {"대지":"3대지: 당할 자가 없다 (완전한 승리)", "내용":"아무도 유다인을 당할 수 없었다. 하나님이 함께하시면 수의 많고 적음이 문제가 아니다", "예화_적용":"다윗이 골리앗 앞에서 만군의 여호와의 이름으로 나가 승리한 것 (삼상 17:45)"},
        {"대지":"결론", "내용":"오늘 우리에게도 동일한 약속이 있다. 성도가 연합하여 하나님을 의지할 때 어떤 원수도 당할 수 없다", "예화_적용":"롬 8:31 만일 하나님이 우리를 위하시면 누가 우리를 대적하리요"}
