    표5_매튜헨리: [
        {"영어원문":"All the rulers of the provinces, the nobles, the governors, and the king's officers helped the Jews, because the fear of Mordecai had fallen upon them.", "한국어번역":"각 도의 모든 방백과 대신과 총독과 왕의 관리들이 유다인을 도왔으니, 모르드개에 대한 두려움이 그들에게 임했기 때문이다.", "핵심통찰":"권력자들의 협력"},
        {"영어원문":"God can make the powers of this world to serve His purposes and protect His people, even when those powers know not His name.", "한국어번역":"하나님은 이 세상의 권세자들이 그의 이름을 알지 못할지라도 그의 목적에 봉사하며 그의 백성을 보호하게 하실 수 있다.", "핵심통찰":"하나님의 섭리적 사용"},
        {"영어원문":"Mordecai was great in the king's house, and his fame went throughout all the provinces; so that all officers assisted the Jews.", "한국어번역":"모르드개가 왕궁에서 존귀하여 그 명성이 각 도에 퍼지매, 모든 관리가 유다인을 도왔다.", "핵심통찰":"한 사람의 영향력"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"하나님이 보내신 도우미들 - 예상치 못한 곳에서 오는 도움", "예화_적용":"하나님은 의외의 방법으로 도우심을 베푸신다"},
        {"대지":"서론", "내용":"유다인의 생존이 위태로운 순간, 예상치 못한 곳에서 도움이 왔다. 이방 관료들이 유다인을 돕기 시작한 것이다", "예화_적용":"엘리야가 절망할 때 하나님이 7천 명을 남겨두신 것 (왕상 19:18)"},
        {"대지":"1대지: 방백과 대신이 도우니 (이방인의 도움)", "내용":"비유대인 관리들이 유다인을 도왔다. 하나님은 이방인도 자기 백성을 돕는 도구로 사용하신다", "예화_적용":"고레스 왕이 유다인의 귀환을 허락한 것 (스 1:1-4)"},
        {"대지":"2대지: 모르드개를 두려워함 (하나님이 세우신 지도자)", "내용":"관리들이 모르드개를 두려워했다. 이는 모르드개 자체가 아니라 그를 세우신 하나님의 권세 때문이다", "예화_적용":"요셉이 바로 앞에서 존귀하게 되어 이스라엘 가족을 구한 것 (창 45:5-8)"},
        {"대지":"3대지: 유다인을 도우니 (하나님의 보호 방법)", "내용":"하나님은 다양한 방법으로 백성을 보호하신다. 때로는 기적으로, 때로는 사람을 통해 역사하신다", "예화_적용":"느헤미야가 아닥사스다 왕의 도움으로 예루살렘 성벽을 재건한 것 (느 2:1-8)"},
        {"대지":"결론", "내용":"하나님의 도우심은 예상치 못한 방향에서 올 수 있다. 잠 21:1 왕의 마음이 여호와의 손에 있다는 말씀을 기억하자", "예화_적용":"잠 21:1 왕의 마음이 여호와의 손에 있어 물줄기 같이 그가 임의로 인도하시느니라"}
    ],
