    표5_매튜헨리: [
        {"영어원문":"Poratha, Adalia, and Aridatha — names of Persian splendour, yet they perished like their father, for no name can shield the wicked from God's justice.", "한국어번역":"보라다, 아달리아, 아리다다 — 화려한 페르시아식 이름들이지만, 아버지처럼 멸망했으니, 어떤 이름도 악인을 하나님의 공의에서 보호하지 못한다.", "핵심통찰":"화려한 이름의 무력함"},
        {"영어원문":"These sons might have learned from their father's fall, yet they continued in his way, and so shared his doom.", "한국어번역":"이 아들들이 아버지의 몰락에서 교훈을 얻을 수 있었으나, 그의 길을 계속 따랐으므로 그 운명을 함께 나누었다.", "핵심통찰":"교훈을 얻지 못한 자의 결말"},
        {"영어원문":"The names of the heathen gods in which they trusted proved powerless to save them; only the living God has power over life and death.", "한국어번역":"그들이 신뢰한 이교 신들의 이름은 그들을 구원하는 데 무력했으니, 오직 살아 계신 하나님만이 생사의 권세를 가지신다.", "핵심통찰":"참 하나님만이 구원하심"}
    ],
