        {"대지":"서론", "내용":"보라다(풍성한), 아달리아(불의 신을 공경하는), 아리다다(숭고한 존재에게 받은) — 화려한 이름의 하만의 아들들이 하나하나 죽임을 당했다", "예화_적용":"타이타닉호가 '침몰하지 않는 배'라 불렸으나 첫 항해에서 침몰한 것처럼, 인간의 자신감은 한계가 있다"},
        {"대지":"1대지: 보라다 - 풍성함의 한계", "내용":"풍성하다는 뜻의 이름을 가졌지만 생명을 보존하지 못했다. 세상의 부요함은 영혼을 구원하지 못한다", "예화_적용":"부자 청년이 많은 소유에도 영생을 얻지 못하고 근심하며 돌아간 것 (막 10:17-22)"},
        {"대지":"2대지: 아달리아 - 우상 숭배의 결말", "내용":"이교 신의 이름을 딴 자가 참 하나님의 심판 앞에 무너졌다. 우상은 결코 구원하지 못한다", "예화_적용":"엘리야와 바알 선지자들의 갈멜산 대결에서 바알이 무력했던 것 (왕상 18장)"},
        {"대지":"3대지: 아리다다 - 거짓 숭고함의 무너짐", "내용":"숭고한 존재에게 헌신했다는 이름이지만 참된 숭고하신 분은 여호와뿐이시다", "예화_적용":"바벨론의 느부갓네살이 자신을 높였다가 짐승처럼 된 것 (단 4장)"},
        {"대지":"결론", "내용":"오직 예수 그리스도의 이름만이 우리를 구원한다(행 4:12). 세상의 것에 소망을 두지 말고 참된 소망이신 그리스도를 붙잡자", "예화_적용":"행 4:12 다른 이로서는 구원을 받을 수 없나니 천하 사람 중에 구원을 받을 만한 다른 이름을 주신 일이 없음이라"}
