        {"새찬송가":"543", "통일찬송가":"384", "제목":"주 하나님 지으신 모든 세계", "선정이유":"역사를 주관하시는 하나님"},
        {"새찬송가":"446", "통일찬송가":"290", "제목":"주 하나님 크신 능력", "선정이유":"능력으로 완성하시는 하나님"}
