    표5_매튜헨리: [
        {"영어원문":"On that day the number of those that were slain in Shushan the palace was brought before the king. Nothing escapes the notice of Providence.", "한국어번역":"그 날에 도성 수산에서 도륙된 자의 수가 왕 앞에 보고되었다. 섭리의 주목을 벗어나는 것은 아무것도 없다.", "핵심통찰":"하나님의 전지하심"},
        {"영어원문":"The king was informed of the execution done in his own capital; so shall every man give account of himself before the King of kings.", "한국어번역":"왕이 자기 수도에서 행해진 일의 보고를 받았으니, 모든 사람이 왕 중의 왕 앞에서 자신에 대한 진술을 할 것이다.", "핵심통찰":"최후의 보고"},
        {"영어원문":"This report opened the door for further mercy; God's deliverances often come in stages, each one preparing the way for the next.", "한국어번역":"이 보고가 더 큰 은혜의 문을 열었으니, 하나님의 구원은 종종 단계적으로 오며 각 단계가 다음 것을 예비한다.", "핵심통찰":"단계적 구원"}
    ],
