        {"대지":"서론", "내용":"수산에서 벌어진 전투의 결과가 왕에게 보고되었다. 500명과 하만의 아들 10명의 죽음이 공식적으로 기록되었다. 이 보고는 다음 단계의 문을 여는 열쇠가 된다", "예화_적용":"기업의 결산 보고가 미래 전략의 기초가 되듯, 하나님 앞에서의 결산이 다음 단계를 여신다"},
        {"대지":"1대지: 그 날에 (결정적인 순간)", "내용":"'그 날'은 단순한 하루가 아니라 역사의 분기점이었다. 우리의 삶에도 결정적인 '그 날'이 있다", "예화_적용":"마틴 루터가 95개조 반박문을 게시한 1517년 10월 31일처럼, 역사를 바꾸는 하루가 있다"},
        {"대지":"2대지: 수를 왕에게 고하니 (투명한 보고)", "내용":"모든 일이 왕 앞에 보고되었다. 우리의 삶도 하나님 앞에 낱낱이 보고된다. 숨길 수 있는 것은 없다", "예화_적용":"아나니아와 삽비라가 거짓으로 보고하다 심판받은 것 (행 5:1-11) - 하나님 앞의 투명성"},
        {"대지":"3대지: 다음 단계의 문 (단계적 인도)", "내용":"이 보고가 에스더의 추가 요청으로 이어진다(9:12-13). 하나님의 인도는 한 단계씩 전개된다", "예화_적용":"이스라엘이 광야에서 낮에는 구름 기둥, 밤에는 불 기둥을 따라 한 걸음씩 나아간 것 (출 13:21-22)"},
        {"대지":"결론", "내용":"우리의 모든 행위가 하나님 앞에 보고된다. 히 4:13 지으신 것이 하나도 그 앞에 나타나지 않음이 없고. 하나님 앞에 투명한 삶을 살자", "예화_적용":"전 12:14 하나님은 모든 행위와 모든 은밀한 일을 선악간에 심판하시리라"}
