        {"항목":"오백 명 처치", "내용":"수산 도성에서 유다인을 공격한 자 오백 명이 처치되었으며 이는 반유대 세력의 규모를 보여준다", "목회적활용":"대적의 세력이 크더라도 하나님의 보호가 더 크다"},
        {"항목":"왕의 반복 질문", "내용":"아하수에로 왕이 에스더에게 소청과 요구를 반복적으로 묻는 것은 페르시아 궁정 예절로 왕의 관대함을 표현하는 방식이었다", "목회적활용":"하나님은 우리의 필요를 넉넉히 채우시려 하신다"}
