        {"교리":"악에 대한 공의", "설명":"하만의 아들들이 나무에 달린 것은 악에 대한 하나님의 공의로운 심판의 완결", "관련구절":"나 1:3, 시 94:23, 롬 12:19"},
        {"교리":"말씀의 확실성", "설명":"왕의 조서가 반드시 시행되듯 하나님의 말씀도 반드시 이루어진다", "관련구절":"사 55:11, 민 23:19, 마 24:35"}
