        {"항목":"해마다 두 날", "내용":"아달월 14일과 15일을 매년 고정적으로 지키기로 결정. 유대 달력으로 12월경", "목회적활용":"규칙적 신앙생활의 중요성"},
        {"항목":"취소하지 아니함", "내용":"히브리어 '로 야아보르'는 법적 구속력을 가진 표현으로 영구적 의무를 선언", "목회적활용":"하나님과의 언약에 대한 신실한 이행"}
