    표5_매튜헨리: [
        {"영어원문":"The Jews ordained and took upon themselves and their seed this perpetual observance, binding their posterity as well as themselves.", "한국어번역":"유다인들은 자신과 자손에게 이 영구적 준수를 정하고 받아들여, 후손에게도 자신과 같은 의무를 지웠다.", "핵심통찰":"세대를 아우르는 결단"},
        {"영어원문":"All such as joined themselves to them were included, for God's covenant is not confined to one nation.", "한국어번역":"그들에게 연합한 모든 자도 포함되었으니, 하나님의 언약은 한 민족에 국한되지 않기 때문이다.", "핵심통찰":"은혜의 보편성"},
        {"영어원문":"That it should not fail — they resolved never to let this memorial perish; good resolutions should be inviolable.", "한국어번역":"취소하지 아니하리라 — 그들은 이 기념이 사라지지 않도록 결의하였으니, 좋은 결심은 불가침이어야 한다.", "핵심통찰":"결단의 불변성"}
    ],
