        {"영어원문":"It is well when those in authority use their power for the good of the church and the glory of God.", "한국어번역":"권위를 가진 자들이 교회의 유익과 하나님의 영광을 위해 그 권력을 사용할 때 참으로 좋다.", "핵심통찰":"권위의 선한 사용"},
        {"영어원문":"Esther, the daughter of Abihail, is here mentioned by her father's name to show her noble descent and rightful authority.", "한국어번역":"아비하일의 딸 에스더가 여기서 아버지의 이름으로 언급된 것은 그녀의 고귀한 혈통과 정당한 권위를 보여주기 위함이다.", "핵심통찰":"정당한 권위의 근거"}
