        {"영어원문":"The decree included the matters of fastings and their cry, for the feast was preceded by a solemn fast in memory of their distress.", "한국어번역":"이 법령은 금식과 부르짖음에 관한 사항을 포함하였으니, 축제 앞에 그들의 고통을 기념하는 엄숙한 금식이 선행되었기 때문이다.", "핵심통찰":"기쁨 전의 회개"},
        {"영어원문":"Fasting and prayer were the weapons by which this victory was won, and therefore they were rightly made part of the annual commemoration.", "한국어번역":"금식과 기도가 이 승리를 얻은 무기였으므로, 이것들이 연례 기념의 일부가 된 것은 당연하다.", "핵심통찰":"금식과 기도의 능력"},
        {"영어원문":"Those who would rejoice in God's salvation must first humble themselves before Him in fasting and supplication.", "한국어번역":"하나님의 구원을 기뻐하려는 자는 먼저 금식과 간구로 그 앞에 자신을 낮추어야 한다.", "핵심통찰":"겸손이 기쁨의 전제"}
